<?php
namespace App\Http\Controllers\CRM; use App\Http\Controllers\Controller; use App\Models\{Guest,MarketingCampaign,MarketingConsent}; use Illuminate\Http\Request;
class MarketingController extends Controller {public function index(){return view('crm.marketing',['campaigns'=>MarketingCampaign::where('property_id',auth()->user()->property_id)->latest()->paginate(25)]);} public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:150','channel'=>'required|in:email,sms,whatsapp,push','subject'=>'nullable|string|max:255','message'=>'required|string','scheduled_at'=>'nullable|date']);$d+=['property_id'=>auth()->user()->property_id,'created_by'=>auth()->id(),'status'=>$d['scheduled_at']?'scheduled':'draft'];MarketingCampaign::create($d);return back()->with('success','Marketing campaign created.');} public function prepare(MarketingCampaign $campaign){abort_unless($campaign->property_id===auth()->user()->property_id,403);$guestIds=MarketingConsent::where('channel',$campaign->channel)->where('consented',true)->pluck('guest_id');$guests=Guest::where('property_id',$campaign->property_id)->whereIn('id',$guestIds)->get();foreach($guests as $g){$destination=match($campaign->channel){'email'=>$g->email,'sms','whatsapp'=>$g->phone,default=>(string)$g->id};if(!$destination)continue;$campaign->messages()->firstOrCreate(['guest_id'=>$g->id,'destination'=>$destination],['status'=>'queued']);}$campaign->update(['recipients_count'=>$campaign->messages()->count(),'status'=>'ready']);return back()->with('success','Consent-based recipient queue prepared.');}}
